enum QuantileMethod {
  QUANTILE_INVERTED_CDF(0),
  QUANTILE_AVERAGED_INVERTED_CDF(1),
  QUANTILE_CLOSEST_OBSERVATION(2),
  QUANTILE_INTERPOLATED_INVERTED_CDF(3),
  QUANTILE_HAZEN(4),
  QUANTILE_WEIBULL(5),
  QUANTILE_LINEAR(6),
  QUANTILE_MEDIAN_UNBIASED(7),
  QUANTILE_NORMAL_UNBIASED(8),
  QUANTILE_LOWER(9),
  QUANTILE_HIGHER(10),
  QUANTILE_MIDPOINT(11),
  QUANTILE_NEAREST(12);

  final int value;
  const QuantileMethod(this.value);

  static QuantileMethod fromValue(int value) => switch (value) {
    0 => QUANTILE_INVERTED_CDF,
    1 => QUANTILE_AVERAGED_INVERTED_CDF,
    2 => QUANTILE_CLOSEST_OBSERVATION,
    3 => QUANTILE_INTERPOLATED_INVERTED_CDF,
    4 => QUANTILE_HAZEN,
    5 => QUANTILE_WEIBULL,
    6 => QUANTILE_LINEAR,
    7 => QUANTILE_MEDIAN_UNBIASED,
    8 => QUANTILE_NORMAL_UNBIASED,
    9 => QUANTILE_LOWER,
    10 => QUANTILE_HIGHER,
    11 => QUANTILE_MIDPOINT,
    12 => QUANTILE_NEAREST,
    _ => throw ArgumentError('Unknown value for QuantileMethod: $value'),
  };
}

enum BinaryOpCode {
  OP_ADD(0),
  OP_MULTIPLY(1),
  OP_MINIMUM(2),
  OP_MAXIMUM(3),
  OP_FMIN(4),
  OP_FMAX(5),
  OP_LOGADDEXP(6),
  OP_LOGADDEXP2(7),
  OP_GCD(8),
  OP_LCM(9),
  OP_BITWISE_AND(10),
  OP_BITWISE_OR(11),
  OP_BITWISE_XOR(12),
  OP_LOGICAL_AND(13),
  OP_LOGICAL_OR(14),
  OP_LOGICAL_XOR(15),
  OP_SUBTRACT(16),
  OP_DIVIDE(17),
  OP_FLOOR_DIVIDE(18),
  OP_REMAINDER(19),
  OP_FMOD(20),
  OP_POWER(21),
  OP_FLOAT_POWER(22),
  OP_ARCTAN2(23),
  OP_HYPOT(24),
  OP_COPYSIGN(25),
  OP_LEFT_SHIFT(26),
  OP_RIGHT_SHIFT(27),
  OP_HEAVISIDE(28),
  OP_EQUAL(29),
  OP_NOT_EQUAL(30),
  OP_GREATER(31),
  OP_GREATER_EQUAL(32),
  OP_LESS(33),
  OP_LESS_EQUAL(34),
  OP_COUNT(35);

  final int value;
  const BinaryOpCode(this.value);

  static BinaryOpCode fromValue(int value) => switch (value) {
    0 => OP_ADD,
    1 => OP_MULTIPLY,
    2 => OP_MINIMUM,
    3 => OP_MAXIMUM,
    4 => OP_FMIN,
    5 => OP_FMAX,
    6 => OP_LOGADDEXP,
    7 => OP_LOGADDEXP2,
    8 => OP_GCD,
    9 => OP_LCM,
    10 => OP_BITWISE_AND,
    11 => OP_BITWISE_OR,
    12 => OP_BITWISE_XOR,
    13 => OP_LOGICAL_AND,
    14 => OP_LOGICAL_OR,
    15 => OP_LOGICAL_XOR,
    16 => OP_SUBTRACT,
    17 => OP_DIVIDE,
    18 => OP_FLOOR_DIVIDE,
    19 => OP_REMAINDER,
    20 => OP_FMOD,
    21 => OP_POWER,
    22 => OP_FLOAT_POWER,
    23 => OP_ARCTAN2,
    24 => OP_HYPOT,
    25 => OP_COPYSIGN,
    26 => OP_LEFT_SHIFT,
    27 => OP_RIGHT_SHIFT,
    28 => OP_HEAVISIDE,
    29 => OP_EQUAL,
    30 => OP_NOT_EQUAL,
    31 => OP_GREATER,
    32 => OP_GREATER_EQUAL,
    33 => OP_LESS,
    34 => OP_LESS_EQUAL,
    35 => OP_COUNT,
    _ => throw ArgumentError('Unknown value for BinaryOpCode: $value'),
  };
}

/// ============================================================================
/// SECTION 1: CORE COMPLEX TYPE DEFINITIONS
/// ============================================================================
/// Binary-compatible complex number structures matching kiss_fft_cpx
/// and mapped directly to ndarray's custom Complex structures.
final class cpx_t extends ffi.Struct {
  @ffi.Double()
  external double r;

  /// Real component
  @ffi.Double()
  external double i;
}

final class cpx_f_t extends ffi.Struct {
  @ffi.Float()
  external double r;

  /// Real component
  @ffi.Float()
  external double i;
}

/// Pairwise distance functions
enum DistanceMetric {
  METRIC_EUCLIDEAN(0),
  METRIC_COSINE(1),
  METRIC_HAMMING(2),
  METRIC_CHEBYSHEV(3);

  final int value;
  const DistanceMetric(this.value);

  static DistanceMetric fromValue(int value) => switch (value) {
    0 => METRIC_EUCLIDEAN,
    1 => METRIC_COSINE,
    2 => METRIC_HAMMING,
    3 => METRIC_CHEBYSHEV,
    _ => throw ArgumentError('Unknown value for DistanceMetric: $value'),
  };
}

